import{_ as i,a0 as n,w as u,s as a,ao as l,I as p,x as e,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"有研究表明，推特能夠推動開源項目的普及 | LCTT x X-CMD","titleTemplate":false,"description":"有研究表明，推特能夠推動開源項目的普及 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有研究表明，推特能夠推動開源項目的普及 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有研究表明，推特能夠推動開源項目的普及 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220615 According to studies, Twitter Drives Open Source Projects Popularity","title":"有研究表明，推特能夠推動開源項目的普及","tag":"202206","desc":""},"relativePath":"202206/20220615 According to studies, Twitter Drives Open Source Projects Popularity.md","filePath":"[post].md"}'),d={name:"202206/20220615 According to studies, Twitter Drives Open Source Projects Popularity.md"};function T(f,t,m,g,w,x){const o=n("Link");return u(),a("div",null,[t[15]||(t[15]=l('<h1 id="有研究表明-推特能夠推動開源項目的普及" tabindex="-1">有研究表明，推特能夠推動開源項目的普及 <a class="header-anchor" href="#有研究表明-推特能夠推動開源項目的普及" aria-label="Permalink to “有研究表明，推特能夠推動開源項目的普及”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/06/twiiter.jpg" alt="推特"></p><p>由 HongBo Fang 博士領導的研究團隊發現，推特是一種吸引更多人關注和貢獻 GitHub 開源項目的有效方式。Fang 博士在國際軟件工程會議上發表了這項名為“‘這真是太棒了！’估計推文對開源項目受歡迎程度和新貢獻者的影響”的研究，並獲得了傑出論文獎。這項研究顯示，發送和一個項目有關的推文，導致了該項目受歡迎程度增加了 7%（在 GitHub 上至少增加了一個星標），貢獻者數量增加了 2%。一個項目收到的推文越多，它收到的星標和貢獻者就越多。</p><p>Fang 説：“我們已經意識到社交媒體在開源社區中變得越來越重要，吸引關注和新的貢獻者將帶來更高質量和更好的軟件。”</p><p>大多數開源軟件都是由志願者創建和維護的。參與項目的人越多，結果就越好。開發者和其他人使用該軟件、報告問題並努力解決這些問題。然而，不受歡迎的項目有可能得不到應有的關注。這些勞動力（幾乎都是志願者），維護了數百萬人每天依賴的軟件。例如，幾乎每個 HTTPS 網站都使用開源的 OpenSSL 保護其內容。Heartbleed 是 OpenSSL 中發現的一個安全漏洞，在 2014 年被發現後，企業花費了數百萬美元來修復它。另一個開源軟件 cURL 允許連接的設備相互發送數據，並安裝在大約 10 億台設備上。開源軟件之多，不勝枚舉。</p><p>此次“推特對提高開源項目的受歡迎程度和吸引新貢獻者的影響”的研究，其實是 “Vasilescu 數據挖掘與社會技術研究實驗室”（STRUDEL）的一個更大項目的其中一部分，該研究着眼於如何建立開源社區並且其工作更具可持續性。畢竟，支撐現代技術的數字基礎設施、道路和橋樑都是開源軟件。如果維護不當，這些基礎設施可能會崩潰。</p><p>研究人員檢查了 44544 條推文，其中包含指向 2370 個開源 GitHub 存儲庫的鏈接，以證明這些推文確實吸引了新的星標和項目貢獻者。在這項研究中，研究人員使用了一種科學的方法：將推特上提及的 GitHub 項目的星標和貢獻者的增加，與推特上未提及的一組項目進行了比較。該研究還描述了高影響力推文的特徵、可能被帖子吸引到項目的人的類型，以及這些人與通過其他方式吸引的貢獻者有何不同。來自項目支持者而不是開發者的推文最能吸引注意力。請求針對特定任務或項目提供幫助的帖子會收到更高的回覆率。推文往往會吸引新的貢獻者，<strong>他們是 GitHub 的新手，但不是經驗不足的程序員</strong>。還有，<strong>新的關注可能不會帶來新的幫助</strong>。</p><p>提高項目受歡迎程度也存在其缺點，研究人員討論後認為，它的潛在缺點之一，就是注意力和行動之間的差距。<strong>更多的關注通常會導致更多的功能請求或問題報告，但不一定有更多的開發者來解決它們</strong>。社交媒體受歡迎程度的提高，可能會導致有更多的“巨魔”或“有毒行為”出現在項目周圍。</p><p>（LCTT 譯註：我覺得文章中有三句話寫得很好，於是把它們加粗了，和大家分享。 —— 六開箱）</p><hr>',10)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/06/according-to-studies-twitter-drives-open-source-projects-popularity/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/06/according-to-studies-twitter-drives-open-source-projects-popularity/",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:s(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[4]||(t[4]=[e("lkxed",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const S=i(d,[["render",T]]);export{P as __pageData,S as default};
